"use client"

// ChurchLookup: a church search box for shadcn/ui apps. Pick a church and the form's fields fill
// from Here's My Church. Works with plain forms (a hidden input submits the church ID), controlled
// state, and React Hook Form (spread a FormField's `field` onto it).
import * as React from "react"
import { Command as CommandPrimitive } from "cmdk"
import { Church, LoaderCircle, Search, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Command, CommandGroup, CommandItem, CommandList } from "@/components/ui/command"
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover"
import { useChurchLookup, type UseChurchLookupOptions } from "@/hooks/use-church-lookup"
import {
  applyFill,
  findTargets,
  matchField,
  planFill,
  stringsFor,
  type ChurchRecord,
  type FillPlan,
  type LookupError,
  type SearchResult,
  type Strings,
} from "@/lib/lookup-core"

export interface ChurchLookupProps extends Omit<UseChurchLookupOptions, "onError"> {
  /** Submit the chosen church's ID under this name in a plain form. */
  name?: string
  /** The chosen church's ID. Set it to show a saved church, as on an edit screen. */
  value?: string
  /** Called with the church ID when a church is chosen, and with "" when cleared. */
  onChange?: (id: string) => void
  onBlur?: () => void
  /** The choice was cleared, with the clear button or by editing the name. */
  onClear?: () => void
  /**
   * A church was chosen and its record loaded. Called before the form fills, with what would change
   * (null when nothing fills). Return false to fill the form yourself.
   */
  onFill?: (record: ChurchRecord, plan: FillPlan | null) => boolean | void
  /** A search, "Show more" or a church's record failed, such as for logging. */
  onError?: (error: LookupError | unknown, detail: { query?: string; id?: string }) => void
  /**
   * Which fields to fill: tagged with data-hmc-field or named for the church (church_city), by
   * default. "auto" also fills plain names like city or zip; "tagged" only tagged ones; false none.
   */
  fill?: boolean | "auto" | "tagged"
  /** Fill from `value` when it's first shown, as when a saved church should refresh the form. */
  fillOnLoad?: boolean
  /** The id of the form to fill. Defaults to the enclosing form, then the whole page. */
  form?: string
  /** Replace fields that already have values. */
  overwrite?: boolean
  /** The form won't submit until a church is chosen from the list. */
  required?: boolean
  /** Text language, such as "es". Defaults to the page's. Load other languages with @/lib/lookup-strings. */
  lang?: string
  /** Override any text, such as { label: "Your parish" }. */
  strings?: Partial<Strings>
  /** The accessible name. Defaults to "Church". */
  label?: string
  placeholder?: string
  /** "compact" rows (the default) or "comfortable" ones with larger icons. */
  density?: "compact" | "comfortable"
  /** The icon beside each result, or null for none. Defaults to a church. */
  icon?: React.ReactNode
  /** The icon in the search box. */
  searchIcon?: React.ReactNode
  /** Show how far each church is. Defaults to true. */
  showDistance?: boolean
  id?: string
  disabled?: boolean
  className?: string
  "aria-invalid"?: boolean
  "aria-describedby"?: string
}

const inputClass =
  "placeholder:text-muted-foreground dark:bg-input/30 border-input flex h-10 w-full min-w-0 rounded-md border bg-transparent py-1 pr-9 pl-9 text-base shadow-xs transition-[color,box-shadow] outline-none disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive"

const MORE = "__more"
// Layout effects warn during server rendering; on the server there's nothing to lay out anyway.
const useIsoLayoutEffect = typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

export const ChurchLookup = React.forwardRef<HTMLInputElement, ChurchLookupProps>(function ChurchLookup(
  {
    name, value, onChange, onBlur, onClear, onFill, onError, fill = true, fillOnLoad, form, overwrite, required, lang, strings,
    label, placeholder, density = "compact", icon, searchIcon, showDistance = true, id, disabled, className,
    "aria-invalid": invalid, "aria-describedby": describedBy, onResults, onSelect, ...search
  },
  ref
) {
  const t = React.useMemo<Strings>(
    () => ({ ...stringsFor(lang ?? (typeof document === "undefined" ? "" : document.documentElement.lang)), ...strings }),
    [lang, strings]
  )
  const shown = React.useRef(0)
  const [announce, setAnnounce] = React.useState("")
  const lookup = useChurchLookup({
    ...search,
    onSelect,
    onError: (e, query) => {
      setAnnounce(t.error)
      onError?.(e, { query })
    },
    onResults: (d, st) => {
      const n = d.results.length
      setAnnounce(
        d.more ? t.moreFound(n - shown.current)
          : n ? (st.corrected ? `${t.corrected(st.corrected)}. ` : "") + t.found(n)
          : t.noneShort
      )
      shown.current = n
      onResults?.(d, st)
    },
  })
  const [text, setText] = React.useState("")
  // cmdk's highlighted item, kept here so "Show more" can move it to the first new church.
  const [active, setActive] = React.useState("")
  const inputRef = React.useRef<HTMLInputElement>(null)
  const wrapRef = React.useRef<HTMLDivElement>(null)
  React.useImperativeHandle(ref, () => inputRef.current!)
  const chosenId = lookup.selected?.id ?? ""
  const comfy = density === "comfortable"

  // cmdk always marks its input expanded and sets its own id; keep both true to this field, so the
  // popup state is announced and a shadcn FormLabel (htmlFor) points at the input.
  useIsoLayoutEffect(() => {
    const input = inputRef.current
    if (!input) return
    input.setAttribute("aria-expanded", String(lookup.open))
    if (id) input.id = id
  })

  // Required: the form won't submit until a church is chosen, with a message on the search box.
  React.useEffect(() => {
    inputRef.current?.setCustomValidity(required && !chosenId ? t.required : "")
  }, [required, chosenId, t])

  function targets() {
    const scope = (form && document.getElementById(form)) || wrapRef.current?.closest("form")
    const generic = fill === "auto" && Boolean(scope)
    return findTargets(scope || document, fill === "tagged" ? undefined : (el) => matchField(el, generic))
  }

  function fillFrom(record: ChurchRecord) {
    const plan = fill ? planFill(record, targets(), { overwrite }) : null
    if (onFill?.(record, plan) === false || !plan) return
    applyFill(plan.changes)
    setAnnounce(t.filled(plan.changes.length, plan.empty))
  }

  // A value set from outside (a saved church, or a form reset) shows that church.
  React.useEffect(() => {
    if ((value ?? "") === chosenId) return
    if (!value) {
      lookup.select(null)
      setText("")
      return
    }
    let live = true
    lookup.lookup
      .getChurch(value)
      .then((r) => {
        if (!live) return
        const n = String(r.fields.name ?? "")
        lookup.select({ id: r.id, name: n, label: n, locationLabel: "" } as SearchResult)
        setText(n)
        // A saved ID whose listing merged into another: hand back the new ID to store.
        if (r.id !== value) onChange?.(r.id)
        if (fillOnLoad) fillFrom(r)
      })
      .catch((e) => {
        if (!live) return
        setAnnounce(t.loadFail)
        onError?.(e, { id: value })
      })
    return () => {
      live = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value])

  function type(next: string) {
    setText(next)
    setAnnounce("")
    const had = chosenId
    lookup.search(next)
    if (had && next.trim() !== lookup.selected?.name) {
      onChange?.("")
      onClear?.()
    }
  }

  async function more() {
    const added = await lookup.more()
    if (added[0]) setActive(added[0].id)
  }

  async function pick(index: number) {
    const result = lookup.results[index]
    if (!result) return
    setText(result.name)
    let record: ChurchRecord | null
    try {
      record = await lookup.choose(index)
    } catch (e) {
      setAnnounce(t.loadFail)
      onError?.(e, { id: result.id })
      return
    }
    if (!record) return
    onChange?.(record.id)
    fillFrom(record)
  }

  function clear() {
    lookup.reset()
    setText("")
    onChange?.("")
    onClear?.()
    inputRef.current?.focus()
  }

  const showEmpty = !lookup.loading && !lookup.error && lookup.results.length === 0 && lookup.query.length >= (search.minChars ?? 2)
  const churchIcon = icon === undefined ? <Church className={comfy ? "size-5" : "size-4"} aria-hidden="true" /> : icon

  return (
    <div ref={wrapRef} className={cn("relative w-full", className)} data-slot="church-lookup">
      <Command shouldFilter={false} loop label={label ?? t.label} value={active} onValueChange={setActive} className="h-auto overflow-visible bg-transparent">
        <Popover open={lookup.open} onOpenChange={lookup.setOpen}>
          <PopoverAnchor asChild>
            <div className="relative">
              <span className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 grid size-4 -translate-y-1/2 place-items-center [&_svg]:size-4" aria-hidden="true">
                {searchIcon ?? <Search />}
              </span>
              <CommandPrimitive.Input
                ref={inputRef}
                value={text}
                onValueChange={type}
                onBlur={onBlur}
                onFocus={() => lookup.results.length > 0 && lookup.setOpen(true)}
                onKeyDown={(e) => {
                  // Down on "Show more" loads more instead of wrapping to the top.
                  if (e.key === "ArrowDown" && active === MORE && lookup.hasMore) {
                    e.preventDefault()
                    void more()
                  } else if (e.key === "Enter" && lookup.error) {
                    e.preventDefault()
                    lookup.retry()
                  }
                }}
                placeholder={placeholder ?? t.placeholder}
                disabled={disabled}
                aria-invalid={invalid}
                aria-describedby={describedBy}
                aria-required={required || undefined}
                className={inputClass}
              />
              {lookup.loading ? (
                <LoaderCircle className="text-muted-foreground absolute top-1/2 right-3 size-4 -translate-y-1/2 animate-spin motion-reduce:animate-[spin_2s_linear_infinite]" aria-hidden="true" />
              ) : chosenId ? (
                <button
                  type="button"
                  onClick={clear}
                  disabled={disabled}
                  aria-label={t.clear}
                  className="text-muted-foreground hover:text-foreground hover:bg-accent focus-visible:ring-ring/50 absolute top-1/2 right-1.5 grid size-7 -translate-y-1/2 place-items-center rounded-sm outline-none focus-visible:ring-[3px]"
                >
                  <X className="size-4" aria-hidden="true" />
                </button>
              ) : null}
            </div>
          </PopoverAnchor>
          <PopoverContent
            align="start"
            sideOffset={6}
            className="w-(--radix-popover-trigger-width) min-w-[280px] p-0"
            aria-label={t.label}
            onOpenAutoFocus={(e) => e.preventDefault()}
            onMouseDown={(e) => e.preventDefault()}
            onInteractOutside={(e) => {
              if (wrapRef.current?.contains(e.target as Node)) e.preventDefault()
            }}
          >
            {lookup.corrected && lookup.results.length > 0 && (
              <p className="text-muted-foreground px-3 pt-2 text-xs" data-slot="church-lookup-corrected">{t.corrected(lookup.corrected)}</p>
            )}
            <CommandList className="max-h-[min(60vh,26rem)]">
              {lookup.error ? (
                <div className="text-muted-foreground px-3 py-4 text-sm">
                  <p>{t.error}</p>
                  <button type="button" onClick={lookup.retry} className="text-foreground hover:bg-accent mt-2 rounded-md border px-3 py-1.5 font-medium">
                    {t.retry}
                  </button>
                </div>
              ) : showEmpty ? (
                <p className="text-muted-foreground px-3 py-4 text-sm">
                  {t.none}
                  <a className="text-foreground underline underline-offset-4" href="https://heresmychurch.com" target="_blank" rel="noopener">
                    {t.add}
                  </a>
                </p>
              ) : null}
              {lookup.results.length > 0 && (
                <CommandGroup>
                  {lookup.results.map((r, i) => (
                    <CommandItem
                      key={r.id}
                      value={r.id}
                      onSelect={() => void pick(i)}
                      className={cn("group", comfy ? "min-h-14 gap-3 py-2" : "min-h-11 gap-2.5 py-1")}
                    >
                      {churchIcon !== null && (
                        <span className={cn("bg-primary/10 text-primary grid shrink-0 place-items-center rounded-md", comfy ? "size-10" : "size-7")}>
                          {churchIcon}
                        </span>
                      )}
                      <span className="min-w-0 flex-1">
                        <span className={cn("block font-medium", comfy ? "text-[0.9375rem]" : "truncate")}>{r.name}</span>
                        <span className="text-muted-foreground group-data-[selected=true]:text-foreground/75 block truncate text-xs">{r.locationLabel}</span>
                      </span>
                      {showDistance && r.distanceKm != null && (
                        <span className="text-muted-foreground group-data-[selected=true]:text-foreground/75 shrink-0 text-xs tabular-nums">
                          {r.distanceKm < 10 ? r.distanceKm : Math.round(r.distanceKm)} km
                        </span>
                      )}
                    </CommandItem>
                  ))}
                  {lookup.hasMore && (
                    <CommandItem
                      value={MORE}
                      onSelect={() => void more()}
                      disabled={lookup.loadingMore}
                      className="text-primary min-h-11 justify-center font-medium"
                    >
                      {lookup.loadingMore ? t.loading : t.more}
                    </CommandItem>
                  )}
                </CommandGroup>
              )}
            </CommandList>
            <div className="text-muted-foreground flex items-center justify-between gap-2 border-t px-3 py-2 text-xs">
              <span>
                {t.dataFrom}{" "}
                <a className="text-foreground font-medium" href="https://heresmychurch.com" target="_blank" rel="noopener">
                  Here’s My Church
                </a>
              </span>
              <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">
                © OpenStreetMap
              </a>
            </div>
          </PopoverContent>
        </Popover>
      </Command>
      {name ? <input type="hidden" name={name} value={chosenId} /> : null}
      <span className="sr-only" role="status" aria-live="polite">
        {announce}
      </span>
    </div>
  )
})

"use client"

// useChurchLookup: Lookup's search engine as a React hook, for building your own church picker.
// The debounce, settled search, "Show more", stale-result handling and record loading all live in
// @/lib/lookup-core, the same engine the <church-lookup> element uses.
import * as React from "react"

import {
  createLookupController,
  type ChurchRecord,
  type ControllerState,
  type Lookup,
  type SearchParams,
  type SearchResult,
} from "@/lib/lookup-core"

export interface UseChurchLookupOptions extends SearchParams {
  /** Your app's name, sent with requests. Use "lookup-demo" while testing. */
  client?: string
  /** Point at another Lookup server. Defaults to https://lookup.heresmychurch.com. */
  baseUrl?: string
  /** Bring your own client, such as one with a custom fetch. */
  lookup?: Lookup
  /** Results arrived. `more` is true when they came from more(). `state` is the search state now. */
  onResults?: (detail: { query: string; results: SearchResult[]; settled: boolean; more: boolean }, state: Readonly<ControllerState>) => void
  /** A search or "Show more" failed. */
  onError?: (error: unknown, query: string) => void
  /** A church is about to be chosen. Return false to cancel. */
  onSelect?: (result: SearchResult) => boolean | void
}

export interface UseChurchLookup extends ControllerState {
  /** Call with what the person typed. */
  search: (text: string) => void
  /** Choose a result by index (the highlighted one by default) and load its full record. */
  choose: (index?: number) => Promise<ChurchRecord | null>
  /** Show the next page of results. Resolves to the rows it added. */
  more: () => Promise<SearchResult[]>
  /** Search the current text again, such as after an error. */
  retry: () => void
  /** Mark a church as chosen without searching, such as a saved one. */
  select: (result: SearchResult | null) => void
  move: (dir: 1 | -1) => void
  highlight: (index: number) => void
  setOpen: (open: boolean) => void
  reset: () => void
  /** The underlying client, for getChurch, meta, contribute and confirm. */
  lookup: Lookup
}

export function useChurchLookup(options: UseChurchLookupOptions = {}): UseChurchLookup {
  const opts = React.useRef(options)
  opts.current = options
  const ctl = React.useMemo(() => {
    const c = createLookupController({
      lookup: opts.current.lookup,
      client: opts.current.client,
      baseUrl: opts.current.baseUrl,
      // Every SearchParams key passes through, read when each search runs.
      params: () => opts.current,
      onChange: (s) => setState({ ...s }),
      onResults: (d) => opts.current.onResults?.(d, c.state),
      onError: (e, q) => opts.current.onError?.(e, q),
      onSelect: (r) => opts.current.onSelect?.(r),
    })
    return c
  }, [])
  const [state, setState] = React.useState<ControllerState>(() => ({ ...ctl.state }))
  React.useEffect(() => () => ctl.destroy(), [ctl])

  return {
    ...state,
    search: ctl.input,
    choose: ctl.choose,
    more: ctl.more,
    retry: ctl.retry,
    select: ctl.select,
    move: ctl.move,
    highlight: ctl.highlight,
    setOpen: (open) => (open ? ctl.open() : ctl.close()),
    reset: ctl.reset,
    lookup: ctl.lookup,
  }
}

// Lookup by Here's My Church, headless core v0.3.0. Generated from @heresmychurch/lookup
// (packages/sdk/src) by scripts/build-registry.mjs. MIT. https://lookup.heresmychurch.com/docs
/* eslint-disable */

// ── client.ts ──
// @heresmychurch/lookup core client. No dependencies.

export interface SearchOptions {
  near?: string;
  lat?: number;
  lng?: number;
  country?: string;
  region?: string;
  limit?: number;
  /** The person stopped typing. Allows the slower semantic path. */
  settled?: boolean;
  /** Set false to stop the API using the request's approximate location. */
  geo?: boolean;
  signal?: AbortSignal;
}

export interface SearchResult {
  id: string;
  name: string;
  label: string;
  locationLabel: string;
  street: string | null;
  city: string | null;
  nearestPlace: string | null;
  region: string;
  regionName: string;
  country: string;
  countryName: string;
  latitude: number;
  longitude: number;
  denomination: string | null;
  completeness: number;
  distanceKm: number | null;
  band: number;
  source: "lexical" | "semantic" | "both";
}

export interface SearchResponse {
  query: string;
  results: SearchResult[];
  /** More churches ranked past `limit`. Ask again with a higher limit to get them. */
  hasMore?: boolean;
  /** The place understood from the query or `near`, such as Dallas, TX. */
  place: { name: string; region: string; country: string } | null;
  /** The spelling searched instead of what was typed, or null. */
  corrected: string | null;
  /** A fallback answer: part of the search didn't run. */
  degraded: boolean;
  /** Whether semantic search ran. */
  semantic?: "used" | "skipped" | "off" | "failed";
  attribution: string;
}

export interface ChurchRecord {
  id: string;
  /** Only with { follow: false }: this listing merged into another. Load that ID instead. */
  movedTo?: string;
  /** The ID you asked for, when it merged into this church. Store this record's `id` instead. */
  movedFrom?: string;
  fields: Record<string, unknown> & { name: string; serviceTimes: { raw: string | null } };
  missing: string[];
  completeness: number;
  hints: { nearestPlace: string | null };
  attribution: string;
}

/** What happened to one contributed field. See the API docs for each status. */
export type FieldStatus = "live" | "in_review" | "not_applied" | "rejected" | "try_again" | "coming_soon";
export interface ContributionResult {
  churchId: string;
  sandbox?: boolean;
  results: { field: string; status: FieldStatus; message?: string }[];
}
export interface ConfirmResult { churchId: string; sandbox?: boolean; status: "confirmed" | FieldStatus; message?: string; lastVerified?: number }
export interface Meta {
  fields: string[];
  contributableFields: Record<string, { countries: "all" | string[]; review: "live" | "moderated"; status?: "coming_soon" }>;
  completenessWeights: Record<string, number>;
  attribution: string;
}

export class LookupError extends Error {
  status: number;
  /** Seconds to wait before trying again, on a 429 or 503. */
  retryAfter?: number;
  /** A stable reason: invalid, not_found, rate_limited, overloaded, unavailable, … */
  code?: string;
  constructor(status: number, message: string, retryAfter?: number, code?: string) {
    super(message);
    this.name = "LookupError";
    this.status = status;
    this.retryAfter = retryAfter;
    this.code = code;
  }
}

export interface LookupOptions {
  baseUrl?: string;
  /** Your tool's name, such as "my-chms". Self-declared; shown to reviewers as declared. */
  client?: string;
  fetch?: typeof fetch;
}

export function createLookup(opts: LookupOptions = {}) {
  const base = (opts.baseUrl ?? "https://lookup.heresmychurch.com").replace(/\/+$/, "") + "/v1";
  const f = opts.fetch ?? fetch.bind(globalThis);

  async function get<T>(path: string, signal?: AbortSignal, init?: RequestInit): Promise<T> {
    const res = await f(base + path, { signal, ...init });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) throw new LookupError(res.status, body.error ?? res.statusText, Number(res.headers.get("retry-after")) || undefined, body.code);
    return body;
  }

  const post = <T>(path: string, body: unknown) =>
    get<T>(path, undefined, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });

  return {
    search(q: string, o: SearchOptions = {}): Promise<SearchResponse> {
      const p = new URLSearchParams({ q });
      for (const k of ["near", "lat", "lng", "country", "region", "limit"] as const) if (o[k] != null) p.set(k, String(o[k]));
      if (o.settled) p.set("settled", "1");
      if (o.geo === false) p.set("geo", "off");
      if (opts.client) p.set("client", opts.client);
      return get(`/search?${p}`, o.signal);
    },
    /** The autofill record. An ID whose listing merged into another loads that church, with `movedFrom`. */
    async getChurch(id: string, o: { signal?: AbortSignal; follow?: boolean } = {}): Promise<ChurchRecord> {
      const one = (i: string) => get<ChurchRecord>(`/churches/${encodeURIComponent(i)}`, o.signal);
      const rec = await one(id);
      return rec.movedTo && o.follow !== false ? { ...(await one(rec.movedTo)), movedFrom: id } : rec;
    },
    /** Field names, which fields can be contributed and how each is reviewed. */
    meta(): Promise<Meta> {
      return get("/meta");
    },
    /** Send corrections. Each field comes back live, in review, or with a reason. */
    contribute(id: string, changes: { field: string; value: unknown }[]): Promise<ContributionResult> {
      return post(`/churches/${encodeURIComponent(id)}/contributions`, { client: opts.client ?? "unknown", changes });
    },
    /** "Still correct": bumps the church's last-verified date. */
    confirm(id: string): Promise<ConfirmResult> {
      return post(`/churches/${encodeURIComponent(id)}/confirm`, { client: opts.client ?? "unknown" });
    },
  };
}

export type Lookup = ReturnType<typeof createLookup>;

// ── dom.ts ──
export type FieldTarget = HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;

/** Set a value the way a person typing would, so frameworks that track input (React) see it. */
export function setNativeValue(el: FieldTarget, value: string): void {
  const proto = el instanceof HTMLSelectElement ? HTMLSelectElement.prototype : el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")!.set!.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
}

// ── strings.ts ──
// Text the widget shows or announces. English is built in; Spanish, French, German, Portuguese and
// Polish load as small separate files (strings-es.js and so on) so the element stays small. Pick a
// language with `lang` (or the page's), and override any string with the `strings` property.

export interface Strings {
  label: string;
  placeholder: string;
  /** Shown when a search finds nothing; the add link follows it. */
  none: string;
  add: string;
  /** Announced when a search finds nothing. */
  noneShort: string;
  error: string;
  found: (n: number) => string;
  /** The row after the results that loads more, and its text while loading. */
  more: string;
  loading: string;
  /** Announced when more results are added. */
  moreFound: (n: number) => string;
